from tornado.web import Application
from tornado.httpclient import HTTPRequest
from unittest.mock import patch, Mock
from tornado.escape import json_encode
from tornado.auth import GoogleOAuth2Mixin

class TestGetAuthenticatedUser(AsyncHTTPTestCase):
    def get_app(self):
        return Application([
            (r"/", GoogleOAuth2Mixin.get_authenticated_user),
        ])

    @patch('tornado.auth.GoogleOAuth2Mixin.get_auth_http_client')
    @patch('tornado.auth.GoogleOAuth2Mixin.get_google_oauth_settings')
    @patch('tornado.auth.GoogleOAuth2Mixin.escape')
    def test_get_authenticated_user(self, mock_escape, mock_settings, mock_http):
        mock_settings.return_value = {"key": "test_key", "secret": "test_secret"}
        mock_http.return_value = Mock()
        mock_http.return_value.fetch.return_value = Mock(body=json_encode({"access_token": "test_token"}))

        request = HTTPRequest(
            "/",
            method="POST",
            body=json_encode({
                "redirect_uri": "http://localhost:8000/",
                "code": "test_code",
                "client_id": "test_key",
                "client_secret": "test_secret",
            }),
            headers={"Content-Type": "application/x-www-form-urlencoded"},
        )
        response = self.fetch(request)

        mock_settings.assert_called_once_with()
        mock_http.assert_called_once_with()
        mock_http.return_value.fetch.assert_called_once_with(
            GoogleOAuth2Mixin._OAUTH_ACCESS_TOKEN_URL,
            method="POST",
            headers={"Content-Type": "application/x-www-form-urlencoded"},
            body="redirect_uri=http%3A%2F%2Flocalhost%3A8000%2F&code=test_code&client_id=test_key&client_secret=test_secret&grant_type=authorization_code",
        )
        mock_escape.json_decode.assert_called_once_with(response.body)
        assert response.body == {"access_token": "test_token"}

if __name__ == "__main__":
    pytest.main()
